CREATE TABLE "TB_DERIV" (
  "DERIV_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ISU_CD" VARCHAR(50) NOT NULL, "ISU_NM" VARCHAR(200), "DERIV_TP" VARCHAR(20) NOT NULL,
  "MKT_CD" VARCHAR(30) NOT NULL, "UNDERLYING_CD" VARCHAR(50), "UNDERLYING_NM" VARCHAR(200),
  "EXPIRATION_CD" VARCHAR(20), "STRIKE_PRC" NUMERIC(20,6), "CALL_PUT_TP" VARCHAR(20),
  "DATA_SRC_CD" VARCHAR(30) NOT NULL, "USE_YN" CHAR(1) NOT NULL DEFAULT 'Y',
  "DEL_YN" CHAR(1) NOT NULL DEFAULT 'N', "CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_DERIV_01" UNIQUE ("ISU_CD"),
  CONSTRAINT "CK_TB_DERIV_01" CHECK ("DERIV_TP" IN ('FUTURE','OPTION')),
  CONSTRAINT "CK_TB_DERIV_02" CHECK ("USE_YN" IN ('Y','N')),
  CONSTRAINT "CK_TB_DERIV_03" CHECK ("DEL_YN" IN ('Y','N'))
);
CREATE INDEX "IDX_TB_DERIV_01" ON "TB_DERIV" ("DERIV_TP","MKT_CD","EXPIRATION_CD");

CREATE TABLE "TB_DERIV_DAY" (
  "DERIV_DAY_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "DERIV_ID" BIGINT NOT NULL REFERENCES "TB_DERIV"("DERIV_ID"), "TRADE_DT" DATE NOT NULL,
  "OPEN_PRC" NUMERIC(20,6), "HIGH_PRC" NUMERIC(20,6), "LOW_PRC" NUMERIC(20,6),
  "CLS_PRC" NUMERIC(20,6), "SETTLE_PRC" NUMERIC(20,6), "CHG_AMT" NUMERIC(20,6),
  "CHG_RT" NUMERIC(12,6), "TRD_VOL" NUMERIC(30,4), "TURNOVER_AMT" NUMERIC(30,4),
  "OPEN_INT" NUMERIC(30,4), "DATA_SRC_CD" VARCHAR(30) NOT NULL,
  "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',
  "COLLECT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_DERIV_DAY_01" UNIQUE ("DERIV_ID","TRADE_DT"),
  CONSTRAINT "CK_TB_DERIV_DAY_01" CHECK ("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR'))
);
CREATE INDEX "IDX_TB_DERIV_DAY_01" ON "TB_DERIV_DAY" ("DERIV_ID","TRADE_DT" DESC);

CREATE TABLE "TB_BOND" (
  "BOND_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ISU_CD" VARCHAR(50) NOT NULL, "ISU_NM" VARCHAR(200), "BOND_TP" VARCHAR(100),
  "MKT_CD" VARCHAR(30) NOT NULL, "ISSUER_NM" VARCHAR(200), "ISSUE_DT" DATE,
  "MATURITY_DT" DATE, "COUPON_RT" NUMERIC(12,6), "PAR_VAL" NUMERIC(30,4),
  "DATA_SRC_CD" VARCHAR(30) NOT NULL, "USE_YN" CHAR(1) NOT NULL DEFAULT 'Y',
  "DEL_YN" CHAR(1) NOT NULL DEFAULT 'N', "CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_BOND_01" UNIQUE ("ISU_CD"),
  CONSTRAINT "CK_TB_BOND_01" CHECK ("USE_YN" IN ('Y','N')),
  CONSTRAINT "CK_TB_BOND_02" CHECK ("DEL_YN" IN ('Y','N'))
);
CREATE INDEX "IDX_TB_BOND_01" ON "TB_BOND" ("MKT_CD","MATURITY_DT");

CREATE TABLE "TB_BOND_TRD_DAY" (
  "BOND_TRD_DAY_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "BOND_ID" BIGINT NOT NULL REFERENCES "TB_BOND"("BOND_ID"), "TRADE_DT" DATE NOT NULL,
  "OPEN_PRC" NUMERIC(20,6), "HIGH_PRC" NUMERIC(20,6), "LOW_PRC" NUMERIC(20,6),
  "CLS_PRC" NUMERIC(20,6), "CLS_YLD_RT" NUMERIC(12,6), "CHG_AMT" NUMERIC(20,6),
  "CHG_RT" NUMERIC(12,6), "TRD_VOL" NUMERIC(30,4), "TURNOVER_AMT" NUMERIC(30,4),
  "DATA_SRC_CD" VARCHAR(30) NOT NULL, "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',
  "COLLECT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_BOND_TRD_DAY_01" UNIQUE ("BOND_ID","TRADE_DT"),
  CONSTRAINT "CK_TB_BOND_TRD_DAY_01" CHECK ("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR'))
);
CREATE INDEX "IDX_TB_BOND_TRD_DAY_01" ON "TB_BOND_TRD_DAY" ("BOND_ID","TRADE_DT" DESC);

INSERT INTO "TB_DERIV" ("ISU_CD","ISU_NM","DERIV_TP","MKT_CD","EXPIRATION_CD","DATA_SRC_CD")
SELECT DISTINCT "ISU_CD","ISU_NM",'FUTURE','GENERAL',"EXPIRATION_CD",'KRX' FROM "TB_KRX_FUT_DAY"
ON CONFLICT ("ISU_CD") DO NOTHING;
INSERT INTO "TB_DERIV_DAY" ("DERIV_ID","TRADE_DT","OPEN_PRC","HIGH_PRC","LOW_PRC","CLS_PRC",
  "TRD_VOL","TURNOVER_AMT","OPEN_INT","DATA_SRC_CD","DATA_STS")
SELECT d."DERIV_ID",k."BASE_DT",k."OPEN_PRC",k."HIGH_PRC",k."LOW_PRC",k."CLS_PRC",k."TRD_VOL",
  k."TRD_AMT",k."OPEN_INT",'KRX','FRESH' FROM "TB_KRX_FUT_DAY" k JOIN "TB_DERIV" d ON d."ISU_CD"=k."ISU_CD"
ON CONFLICT ("DERIV_ID","TRADE_DT") DO NOTHING;
DROP TABLE "TB_KRX_FUT_DAY";

COMMENT ON TABLE "TB_DERIV" IS '공급자 공통 파생상품 기준정보';
COMMENT ON TABLE "TB_DERIV_DAY" IS '공급자 공통 파생상품 일별매매정보';
COMMENT ON TABLE "TB_BOND" IS '공급자 공통 개별채권 기준정보';
COMMENT ON TABLE "TB_BOND_TRD_DAY" IS '공급자 공통 개별채권 일별매매정보';
